const dayVisuals=Array.from({length:366},(_,i)=>{
 const src=imageSources[i%imageSources.length];
 const rotation=((i*7)%7)-3;
 const zoom=1.02+((i*13)%17)/100;
 const x=38+((i*17)%25);
 const y=38+((i*19)%25);
 const overlay=0.12+((i*11)%10)/100;
 return {day:i+1,name:src[0],telugu:src[1],url:src[2],rotation,zoom,x,y,overlay};
});
const fetchDeityImage=async(name:string,seed=Date.now(),recent:any[]=[])=>{const q=name+" Hindu deity";const url="https://commons.wikimedia.org/w/api.php?"+new URLSearchParams({action:"query",generator:"search",gsrsearch:q,gsrnamespace:"6",gsrlimit:"20",prop:"imageinfo",iiprop:"url|extmetadata",iiurlwidth:"2400",format:"json",origin:"*"}).toString();const res=await fetch(url,{headers:{"Api-User-Agent":"DharmaPulse/1.0"}});if(!res.ok)throw new Error("image search failed");const data=await res.json();const pages=Object.values(data?.query?.pages||{}) as any[];const candidates=pages.map(p=>{const ii=p.imageinfo?.[0];return ii?{url:ii.thumburl||ii.url,title:String(p.title||"").replace(/^File:/,""),source:ii.descriptionurl||("https://commons.wikimedia.org/wiki/"+encodeURIComponent(String(p.title||""))),license:ii.extmetadata?.LicenseShortName?.value||"",artist:ii.extmetadata?.Artist?.value||""}:null}).filter(Boolean).filter((x:any)=>x.url&&/\.(jpe?g|png|webp)$/i.test(x.url));if(!candidates.length)throw new Error("no deity image");const fresh=candidates.filter((x:any)=>!recent.some((r:any)=>r.url===x.url));const pool=fresh.length?fresh:candidates;return pool[Math.abs(seed)%pool.length]};

const calendarGoogleUrl=(date:string,title:string,description:string)=>{const start=date.replaceAll("-","");const d=new Date(date+"T12:00:00");d.setDate(d.getDate()+1);const end=d.toISOString().slice(0,10).replaceAll("-","");return `https://calendar.google.com/calendar/render?action=TEMPLATE&dates=${start}/${end}&text=${encodeURIComponent(title)}&details=${encodeURIComponent(description)}`};
const downloadIcs=(events:string[][],name="dharmapulse-festivals.ics")=>{const body=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//DharmaPulse//Devotional Calendar//EN","CALSCALE:GREGORIAN","METHOD:PUBLISH",...events.flatMap(e=>{const d=new Date(e[0]+"T12:00:00");d.setDate(d.getDate()+1);const end=d.toISOString().slice(0,10).replaceAll("-","");return ["BEGIN:VEVENT",`UID:dharmapulse-${e[0]}-${e[1].replace(/\\W/g,"")}`,`DTSTART;VALUE=DATE:${e[0].replaceAll("-","")}`,`DTEND;VALUE=DATE:${end}`,`SUMMARY:${e[1]}`,`DESCRIPTION:${e[3]||""}`,"END:VEVENT"]}),"END:VCALENDAR"].join("\\r\\n");const blob=new Blob([body],{type:"text/calendar;charset=utf-8"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)};
